class Solution {
public:
    int findMinimumOperations(string s1, string s2, string s3) {
        int min_len = min({s1.size(), s2.size(), s3.size()});
        int lcp = 0;
        for (int i = 0; i < min_len; i++) {
            if (s1[i] == s2[i] && s2[i] == s3[i]) lcp++;
            else break;
        }
        if (lcp == 0) return -1;
        return s1.size() + s2.size() + s3.size() - 3 * lcp;
    }
};

class Solution {
    public int findMinimumOperations(String s1, String s2, String s3) {
        int minLen = Math.min(s1.length(), Math.min(s2.length(), s3.length()));
        int lcp = 0;
        for (int i = 0; i < minLen; i++) {
            if (s1.charAt(i) == s2.charAt(i) && s2.charAt(i) == s3.charAt(i)) lcp++;
            else break;
        }
        if (lcp == 0) return -1;
        return s1.length() + s2.length() + s3.length() - 3 * lcp;
    }
}

/**
 * @param {string} s1
 * @param {string} s2
 * @param {string} s3
 * @return {number}
 */
var findMinimumOperations = function(s1, s2, s3) {
    const minLen = Math.min(s1.length, s2.length, s3.length);
    let lcp = 0;
    for (let i = 0; i < minLen; i++) {
        if (s1[i] === s2[i] && s2[i] === s3[i]) lcp++;
        else break;
    }
    if (lcp === 0) return -1;
    return s1.length + s2.length + s3.length - 3 * lcp;
};
